class GfG {
    static ArrayList<Integer> kDistanceNodes(Node root, int target, int k) {
        ArrayList<Integer> ans = new ArrayList<>();

        // base case
        if (root == null) return ans;

        Queue<Node> q = new LinkedList<>();
        q.add(root);

        // hash map to map the nodes
        // to their parent nodes.
        HashMap<Node, Node> p = new HashMap<>();
        p.put(root, null);

        Node tar = null;

        // This loop will find the target 
        // node and map all the nodes to 
        // their parent nodes.
        while (!q.isEmpty()) {
            Node curr = q.poll();

            // If current node is target
            if (curr.data == target)
                tar = curr;

            // Map the left child to current
            // node.
            if (curr.left != null) {
                p.put(curr.left, curr);
                q.add(curr.left);
            }

            // Map the right child to current
            // node.
            if (curr.right != null) {
                p.put(curr.right, curr);
                q.add(curr.right);
            }
        }

        q.add(tar);

        // hash map to check if 
        // a node has been visited.
        HashMap<Node, Boolean> vis = new HashMap<>();

        while (!q.isEmpty()) {
            int size = q.size();

            // If the distance is k,
            // then append the elements
            // into result.
            if (k == 0) {
                while (!q.isEmpty()) {
                    Node node = q.poll();
                    ans.add(node.data);
                }
                break;
            }

            while (size-- > 0) {
                Node curr = q.poll();
                vis.put(curr, true);

                if (curr.left != null 
                    && !vis.getOrDefault(curr.left, false))
                    q.add(curr.left);

                if (curr.right != null 
                    && !vis.getOrDefault(curr.right, false))
                    q.add(curr.right);

                Node parent = p.get(curr);
                if (parent != null 
                    && !vis.getOrDefault(parent, false))
                    q.add(parent);
            }

            k--;
        }

        // Sort the result
        Collections.sort(ans);

        return ans;
    }

    static void printList(ArrayList<Integer> v) {
        for (int value : v) {
            System.out.print(value + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {

        // Create a hard coded tree.
        //         20
