using System;
using System.Collections.Generic;

class Node {
    public int data;
    public Node left, right;

    public Node(int x) {
        data = x;
        left = null;
        right = null;
    }
}

class GfG {
    static List<int> KDistanceNodes(Node root, int target, int k) {
        List<int> ans = new List<int>();

        // base case
        if (root == null) return ans;

        Queue<Node> q = new Queue<Node>();
        q.Enqueue(root);

        // hash map to map the nodes
        // to their parent nodes.
        Dictionary<Node, Node> p = new Dictionary<Node, Node>();
        p[root] = null;

        Node tar = null;

        // This loop will find the target 
        // node and map all the nodes to 
        // their parent nodes.
        while (q.Count > 0) {
            Node curr = q.Dequeue();

            // If current node is target
            if (curr.data == target)
                tar = curr;

            // Map the left child to current
            // node.
            if (curr.left != null) {
                p[curr.left] = curr;
                q.Enqueue(curr.left);
            }

            // Map the right child to current
            // node.
            if (curr.right != null) {
                p[curr.right] = curr;
                q.Enqueue(curr.right);
            }
        }

        q.Enqueue(tar);

        // hash map to check if 
        // a node has been visited.
        Dictionary<Node, bool> vis = new Dictionary<Node, bool>();

        while (q.Count > 0) {
            int size = q.Count;

            // If the distance is k,
            // then append the elements
            // into result.
            if (k == 0) {
                while (q.Count > 0) {
                    Node node = q.Dequeue();
                    ans.Add(node.data);
                }
                break;
            }

            while (size-- > 0) {
                Node curr = q.Dequeue();
                vis[curr] = true;

                if (curr.left != null && !vis.ContainsKey(curr.left))
                    q.Enqueue(curr.left);

                if (curr.right != null && !vis.ContainsKey(curr.right))
                    q.Enqueue(curr.right);

                Node parent = p[curr];
                if (parent != null && !vis.ContainsKey(parent))
                    q.Enqueue(parent);
            }

            k--;
        }

        // Sort the result
        ans.Sort();

        return ans;
    }

    static void PrintList(List<int> v) {
        foreach (int value in v) {
            Console.Write(value + " ");
        }
        Console.WriteLine();
    }

    static void Main(string[] args) {

        // Create a hard coded tree.
        //         20
        //       /    \
        //      7      24
        //    /   \
        //   4     3
        //        /  
        //       1    
        Node root = new Node(20);
        root.left = new Node(7);
        root.right = new Node(24);
        root.left.left = new Node(4);
        root.left.right = new Node(3);
        root.left.right.left = new Node(1);

        int target = 7, k = 2;
        List<int> ans = KDistanceNodes(root, target, k);

        PrintList(ans);
    }
}


