function kDistanceNodes(root, target, k) {
    let ans = [];

    // base case
    if (root === null) return ans;

    let q = [];
    q.push(root);

    // hash map to map the nodes
    // to their parent nodes.
    let p = new Map();
    p.set(root, null);

    let tar = null;

    // This loop will find the target 
    // node and map all the nodes to 
    // their parent nodes.
    while (q.length > 0) {
        let curr = q.shift();

        // If current node is target
        if (curr.key === target)
            tar = curr;

        // Map the left child to current
        // node.
        if (curr.left !== null) {
            p.set(curr.left, curr);
            q.push(curr.left);
        }

        // Map the right child to current
        // node.
        if (curr.right !== null) {
            p.set(curr.right, curr);
            q.push(curr.right);
        }
    }

    q.push(tar);

    // hash map to check if 
    // a node has been visited.
    let vis = new Map();

    while (q.length > 0) {
        let size = q.length;

        // If the distance is k,
        // then append the elements
        // into result.
        if (k === 0) {
            while (q.length > 0) {
                let node = q.shift();
                ans.push(node.key);
            }
            break;
        }

        while (size-- > 0) {
            let curr = q.shift();
            vis.set(curr, true);

            if (curr.left !== null && !vis.has(curr.left))
                q.push(curr.left);

            if (curr.right !== null && !vis.has(curr.right))
                q.push(curr.right);

            let parent = p.get(curr);
            if (parent !== null && !vis.has(parent))
                q.push(parent);
        }

        k--;
    }

    // Sort the result
    ans.sort((a, b) => a - b);

    return ans;
}

